/**
 * @suppress
 */
public object FfiConverterTypeMessenger: FfiConverter<Messenger, Pointer> {

    override fun lower(value: Messenger): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): Messenger {
        return Messenger(value)
    }

    override fun read(buf: ByteBuffer): Messenger {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: Messenger) = 8UL

    override fun write(value: Messenger, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



/**
 * Сведения о зарегистрированном аккаунте.
 */
data class FfiAccount (
    /**
     * Идентификатор аккаунта.
     */
    var `accountId`: kotlin.String, 
    /**
     * Идентификатор устройства: по нему адресуется доставка.
     */
    var `deviceId`: kotlin.String, 
    /**
     * Занятое имя пользователя.
     */
    var `username`: kotlin.String
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiAccount: FfiConverterRustBuffer<FfiAccount> {
    override fun read(buf: ByteBuffer): FfiAccount {
        return FfiAccount(
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
        )
    }

    override fun allocationSize(value: FfiAccount) = (
            FfiConverterString.allocationSize(value.`accountId`) +
            FfiConverterString.allocationSize(value.`deviceId`) +
            FfiConverterString.allocationSize(value.`username`)
    )

    override fun write(value: FfiAccount, buf: ByteBuffer) {
            FfiConverterString.write(value.`accountId`, buf)
            FfiConverterString.write(value.`deviceId`, buf)
            FfiConverterString.write(value.`username`, buf)
    }
}



/**
 * Что исчезло вместе с аккаунтом.
 *
 * 🔐 Показывается человеку после удаления. «Готово» без чисел ничем
 * не отличается от «готово» при запросе, который ничего не удалил,
 * а здесь проверить самому уже нечем: аккаунта, которым можно было бы
 * спросить, больше нет.
 */
data class FfiAccountDeletion (
    /**
     * Сколько устройств было у аккаунта.
     */
    var `devices`: kotlin.ULong, 
    /**
     * Сколько недоставленных конвертов удалено.
     */
    var `envelopes`: kotlin.ULong, 
    /**
     * Сколько загруженных вложений удалено.
     *
     * ⚠️ Только загруженных этим аккаунтом. Присланные ему остаются:
     * сервер не знает, кому они предназначались.
     */
    var `attachments`: kotlin.ULong
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiAccountDeletion: FfiConverterRustBuffer<FfiAccountDeletion> {
    override fun read(buf: ByteBuffer): FfiAccountDeletion {
        return FfiAccountDeletion(
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
