/**
 * Ошибка, пересекающая границу FFI.
 *
 * Варианты намеренно грубые. Различие между «неверный тег аутентификации»
 * и «неверная длина» — это оракул для атакующего, а сообщение об ошибке
 * попадает в системный лог платформы, который читается кем угодно.
 */
sealed class FfiException(message: String): kotlin.Exception(message) {
        
    /**
     * Ошибка ядра AEGIS.
     */
        class Core(message: String) : FfiException(message)
        
    /**
     * Входные данные не прошли валидацию на границе.
     */
        class InvalidArgument(message: String) : FfiException(message)
        
    /**
     * В ядре произошла паника.
     *
     * Сообщение паники сознательно **не** передаётся: оно может содержать
     * значения переменных, а значит потенциально — чувствительные данные.
     */
        class Panic(message: String) : FfiException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        
            return when(buf.getInt()) {
            1 -> FfiException.Core(FfiConverterString.read(buf))
            2 -> FfiException.InvalidArgument(FfiConverterString.read(buf))
            3 -> FfiException.Panic(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: FfiException): ULong {
        return 4UL
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Core -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.InvalidArgument -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.Panic -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Режим выхода в сеть.
 */
sealed class FfiProxy {
    
    /**
     * Напрямую: сервер видит IP-адрес.
     */
    object Direct : FfiProxy()
    
    
    /**
     * Через SOCKS5-прокси.
     */
    data class Socks5(
        /**
         * Имя хоста или IP-адрес прокси.
         */
        val `host`: kotlin.String, 
        /**
         * Порт прокси.
         */
        val `port`: kotlin.UShort) : FfiProxy() {
        companion object
    }
    
    /**
     * Через Tor с помощью Orbot на этом устройстве.
     */
    object Orbot : FfiProxy()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiProxy : FfiConverterRustBuffer<FfiProxy>{
    override fun read(buf: ByteBuffer): FfiProxy {
        return when(buf.getInt()) {
            1 -> FfiProxy.Direct
            2 -> FfiProxy.Socks5(
                FfiConverterString.read(buf),
                FfiConverterUShort.read(buf),
                )
            3 -> FfiProxy.Orbot
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiProxy) = when(value) {
        is FfiProxy.Direct -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiProxy.Socks5 -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`host`)
                + FfiConverterUShort.allocationSize(value.`port`)
            )
        }
        is FfiProxy.Orbot -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: FfiProxy, buf: ByteBuffer) {
        when(value) {
            is FfiProxy.Direct -> {
                buf.putInt(1)
                Unit
            }
            is FfiProxy.Socks5 -> {
                buf.putInt(2)
                FfiConverterString.write(value.`host`, buf)
                FfiConverterUShort.write(value.`port`, buf)
                Unit
            }
            is FfiProxy.Orbot -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





